+export function displayedClosing(pool: Pool) {
+  const expenses = sum(pool.consumptions.filter((x) => x.type === 'expense'));
+  const fxEur = sum(pool.consumptions.filter((x) => x.type === 'fx_eur'));
+  return pool.opening + pool.inflows - expenses - fxEur;
+}
+
+export const supportedConsumptionTypes = ['expense', 'fx_eur', 'fx_other'];

