--- /dev/null
+++ b/src/export.test.ts
@@ -0,0 +1,35 @@
+import assert from 'node:assert/strict';
+import { allocateCents, closingCents, worksheetChunks } from './export';
+assert.deepEqual(worksheetChunks([]), []);
+assert.deepEqual(worksheetChunks(new Array(1_048_575)).map((x) => x.length), [1_048_575]);
+assert.deepEqual(worksheetChunks(new Array(1_048_576)).map((x) => x.length),
+  [1_048_575, 1]);
+assert.deepEqual(worksheetChunks(new Array(1_048_577)).map((x) => x.length),
+  [1_048_575, 2]);
+assert.equal(closingCents(10_000n, 5_000n, [1_000n, 2_000n, 3_000n]), 9_000n);
+assert.throws(() => closingCents(-1n, 0n, []), RangeError);
+assert.throws(() => closingCents({ valueOf: () => 10n } as unknown as bigint, 0n, []), RangeError);
+const sparseConsumption = Array<bigint>(2);
+sparseConsumption[1] = 1n;
+assert.throws(() => closingCents(10n, 0n, sparseConsumption), RangeError);
+const inheritedConsumption = Array<bigint>(1);
+const inheritedArrayProto = Object.create(Array.prototype);
+Object.defineProperty(inheritedArrayProto, '0', { value: 1n });
+Object.setPrototypeOf(inheritedConsumption, inheritedArrayProto);
+assert.throws(() => closingCents(10n, 0n, inheritedConsumption), RangeError);
+let consumptionReads = 0;
+const volatileConsumption = [1n];
+Object.defineProperty(volatileConsumption, '0', { get: () => ++consumptionReads === 1 ? 1n : -1n });
+assert.equal(closingCents(10n, 0n, volatileConsumption), 9n);
+assert.equal(consumptionReads, 1);
+const allocated = allocateCents(10_001n, [333_333n, 333_333n, 333_334n]);
+assert.equal(allocated.reduce((a, b) => a + b, 0n), 10_001n);
+assert.deepEqual(allocateCents(1n, [500_000n, 500_000n, 0n]), [1n, 0n, 0n]);
+assert.throws(() => allocateCents(100n, []), RangeError);
+assert.throws(() => allocateCents(100n, [-1n, 1_000_001n]), RangeError);
+assert.throws(() => allocateCents(100n, [600_000n, 600_000n]), RangeError);
+assert.throws(() => allocateCents({ valueOf: () => 100n } as unknown as bigint, [1_000_000n]), RangeError);
+const sparseWeights = Array<bigint>(2); sparseWeights[1] = 1_000_000n;
+assert.throws(() => allocateCents(100n, sparseWeights), RangeError);
+let weightReads = 0;
+const volatileWeights = [1_000_000n];
+Object.defineProperty(volatileWeights, '0', { get: () => ++weightReads === 1 ? 1_000_000n : 0n });
+assert.deepEqual(allocateCents(100n, volatileWeights), [100n]);
+assert.equal(weightReads, 1);
